class LazyLoadingManager{constructor(){this.init();}init(){const checkExisting=()=>{const images=document.querySelectorAll('img[loading="lazy"]');images.forEach(img=>{if (img.complete){img.classList.add('lazy-loaded');}});};if (document.readyState==='loading'){document.addEventListener('DOMContentLoaded',checkExisting);}else{checkExisting();}document.addEventListener('load',(event)=>{const target=event.target;if (target.tagName==='IMG'&&target.getAttribute('loading')==='lazy'){target.classList.add('lazy-loaded');}},true);document.addEventListener('error',(event)=>{const target=event.target;if (target.tagName==='IMG'&&target.getAttribute('loading')==='lazy'){target.classList.add('lazy-error');}},true);}}document.addEventListener('DOMContentLoaded',function (){new LazyLoadingManager();});function reinitializeLazyLoading(){new LazyLoadingManager();}if (typeof module!=='undefined'&&module.exports){module.exports=LazyLoadingManager;}